  s.setProperty('--b6c-ts-py', c.py.toFixed(3));
  s.setProperty('--b6c-ts-mx', c.mx.toFixed(1) + '%');
  s.setProperty('--b6c-ts-my', c.my.toFixed(1) + '%');
  s.setProperty('--b6c-ts-lift', c.l.toFixed(3));
