  t.mx = x * 100; t.my = y * 100; t.l = 1;
  if (reduce) { snap(); return; }
  kick();
}
function rest() {
  t.rx = 0; t.ry = 0; t.px = 0; t.py = 0; t.mx = 50; t.my = 0; t.l = 0;
