var opts = Array.prototype.slice.call(root.querySelectorAll('.b6c-price-tier-opt'));
var thumb = root.querySelector('.b6c-price-tier-thumb');
var amt = root.querySelector('.b6c-price-tier-amt');
var note = root.querySelector('.b6c-price-tier-note');
if (!opts.length || !amt) return;
var plans = [
  { v: 24, note: 'Billed monthly · cancel anytime' },
  { v: 19, note: 'Billed yearly · save 20%' }
];
var mq = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)');
var reduce = !!(mq && mq.matches);
var raf = 0;
function countTo(to) {
  var from = parseFloat(amt.textContent) || 0;
  if (raf) cancelAnimationFrame(raf);
  if (reduce || from === to) { amt.textContent = String(to); return; }
  var t0 = 0, dur = 460;
  amt.classList.add('b6c-price-tier-amt-live');
  raf = requestAnimationFrame(function step(now) {
    if (!t0) t0 = now;
    var p = Math.min(1, (now - t0) / dur);
    var e = 1 - Math.pow(1 - p, 3);
    amt.textContent = String(Math.round(from + (to - from) * e));
    if (p < 1) { raf = requestAnimationFrame(step); }
    else { raf = 0; amt.classList.remove('b6c-price-tier-amt-live'); }
  });
}
function select(i) {
  opts.forEach(function (b, n) { b.setAttribute('aria-pressed', n === i ? 'true' : 'false'); });
  if (thumb) thumb.style.transform = 'translateX(' + (i * 100) + '%)';
  if (note) note.textContent = plans[i].note;
  countTo(plans[i].v);
}
opts.forEach(function (b, i) { b.addEventListener('click', function () { select(i); }); });
select(0);

