var head = root.querySelector('.b6c-expand-card-head');
var ack = root.querySelector('.b6c-expand-card-ack');
var meta = root.querySelector('.b6c-expand-card-meta');
if (!head) return;
function setOpen(open) {
  head.setAttribute('aria-expanded', open ? 'true' : 'false');
  if (open) root.classList.add('b6c-expand-card-open');
  else root.classList.remove('b6c-expand-card-open');
}
setOpen(head.getAttribute('aria-expanded') === 'true');
head.addEventListener('click', function () {
  setOpen(head.getAttribute('aria-expanded') !== 'true');
});
if (ack) {
  ack.addEventListener('click', function () {
    if (ack.disabled) return;
    ack.disabled = true;
    ack.textContent = 'Acknowledged ✓';
    root.classList.add('b6c-expand-card-ack');
    if (meta) meta.textContent = 'SEV-2 · acked by you · 14:36';
  });
}
